    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'lookup',
        description: 'looks things up',
        inputSchema: {
          type: 'object',
          properties: {q: {type: 'string'}},
          required: ['q'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return `found:${String(input.q)}`;
      }
    );

    const sentRounds: SendMessageParams[] = [];
    const base = scriptedProvider([
      [{type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {}}}, STOP_FOR_TOOL],
      [TOOL_CALL, STOP_FOR_TOOL],
      [{type: 'text', text: 'found:x'}, STOP_DONE],
    ]);
    const provider: AIProvider = {
      sendMessage(params: SendMessageParams) {
        sentRounds.push(params);
        return base.sendMessage(params);
      },
      generateStructured: base.generateStructured,
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
    const reply = await orchestrator.processMessage(createSession('search x'));
    const roundTwoMessages = sentRounds[1]?.messages ?? [];
    const {content: results} = roundTwoMessages[roundTwoMessages.length - 1] as ToolResultMessage;
    const rejectionText = results[0]?.content ?? '';

    expect({
      reply,
      receivedInputs,
      rejectedForMissingQuery: rejectionText.includes('"q"') && rejectionText.includes('required'),
    }).toEqual({
      reply: 'found:x',
      receivedInputs: [{q: 'x'}],
      rejectedForMissingQuery: true,
    });
  });
});

